import { readFileSync, writeFileSync } from 'fs';
const p = 'tools/pcb_templates/export.mjs';
let s = readFileSync(p, 'utf8');
const neu = readFileSync('tools/pcb_templates/_hand_analog_ic.mjs', 'utf8').trimEnd() + '\n\n';
const start = s.indexOf('/**\n * 模拟 IC 检测手布');
const end = s.indexOf('/**\n * 分立器件检测手布');
if (start < 0 || end < 0) {
  console.error('markers', start, end);
  process.exit(1);
}
s = s.slice(0, start) + neu + s.slice(end);
// Cu=4
s = s.replace(
  `if (id === 'lab_power' || id === 'lab_amp' || id === 'lab_filter' ||
      id === 'lab_passive' || id === 'lab_discrete' || id === 'lab_analog_ic') {
    n = 2;
  }
  if (id === 'lab_51_led' || id === 'lab_uart') {
    n = 4;
  }`,
  `if (id === 'lab_power' || id === 'lab_amp' || id === 'lab_filter' ||
      id === 'lab_passive' || id === 'lab_discrete') {
    n = 2;
  }
  if (id === 'lab_51_led' || id === 'lab_uart' || id === 'lab_analog_ic') {
    n = 4;
  }`
);
writeFileSync(p, s);
console.log('ok', end - start, '->', neu.length);
